"""Note data for the public-domain classical demos in build_demos.py.

Kept out of build_demos.py so the generator stays readable: this module is pure data,
transcribed from public-domain scores (Bach d.1750, Vivaldi pub.1725, Saint-Saens pub.1886).
The ARRANGEMENT — which line goes on which of the synth's 4 multitimbral parts, the patches
and the velocities — lives in build_demos.py; this is just the notes.

Where the notes came from. The works are public domain; a modern *engraving* of one need not be,
so the edition each transcription was checked against is worth recording. The Goldberg Aria's
32 bars were read off the Mutopia Project's BWV 988 edition (Bach-Gesellschaft source, maintainer
JD Erickson, CC BY-SA 3.0) and every bar's pitch sequence cross-checked against that edition's
MIDI. What is below is note data — pitch and duration, facts of Bach's score rather than of anyone's
typesetting — but the check is only meaningful if you can say what it was checked against.

Two formats:
  * BWV846 / *_HARM: readable note-name or chord tables, one entry per bar.
  * everything else: a run of "onset,duration,midi" triples, times in TICKS of 1/96 beat
    (so 32nd-note triplets and the Largo's 32nd trills stay exact). One string literal per
    bar of the original score; the trailing comment is that bar number. unpack() decodes.
"""

TPB = 96                                   # ticks per beat in the packed strings


def unpack(packed, ch, vel, t0=0.0, transpose=0, minimum=0.0):
    """Packed triples -> the demos.json note rows [t_beats, dur_beats, ch, midi, vel]."""
    out = []
    for tok in packed.split():
        t, d, m = tok.split(",")
        dur = max(int(d) / TPB, minimum)
        out.append([round(t0 + int(t) / TPB, 4), round(dur, 4), ch, int(m) + transpose, vel])
    return out


# ==================== Bach - Prelude in C, BWV 846 (WTC I) ====================
# All 35 bars. Bars 1-32 are the one figure the whole prelude is built from: five pitches
# (2 left hand + 3 right hand) played as 16 sixteenths, "n1 n2 n3 n4 n5 n3 n4 n5" twice.
BWV846 = [
    "C4 E4 G4 C5 E5",   "C4 D4 A4 D5 F5",   "B3 D4 G4 D5 F5",   "C4 E4 G4 C5 E5",    # 1-4    I ii7 V7 I
    "C4 E4 A4 E5 A5",   "C4 D4 F#4 A4 D5",  "B3 D4 G4 D5 G5",   "B3 C4 E4 G4 C5",    # 5-8    (top A = the piece's highest note)
    "A3 C4 E4 G4 C5",   "D3 A3 D4 F#4 C5",  "G3 B3 D4 G4 B4",   "G3 Bb3 E4 G4 C#5",  # 9-12   cadence in the dominant
    "F3 A3 D4 A4 D5",   "F3 Ab3 D4 F4 B4",  "E3 G3 C4 G4 C5",   "E3 F3 A3 C4 F4",    # 13-16  the Fonte sequence
    "D3 F3 A3 C4 F4",   "G3 D4 G4 B4 F5",   "C4 E4 G4 C5 E5",   "C4 G4 Bb4 C5 E5",   # 17-20  home, then C7 opens the coda
    "F3 F4 A4 C5 E5",   "F#3 C4 A4 C5 Eb5", "Ab3 F4 B4 C5 D5",  "G3 F4 G4 B4 D5",    # 21-24  the two diminished sevenths
    "G3 E4 G4 C5 E5",   "G3 D4 G4 C5 F5",   "G3 D4 G4 B4 F5",   "G3 Eb4 A4 C5 F#5",  # 25-28  dominant pedal on G
    "G3 E4 G4 C5 G5",   "G3 D4 G4 C5 F5",   "G3 D4 G4 B4 F5",   "C3 C4 G4 Bb4 E5",   # 29-32  tonic pedal starts
]
# Bars 33-34, where the figure breaks into a free arpeggio (all 16 sixteenths spelled out),
# and bar 35, the final C major chord.
BWV846_CODA = [
    "C3 C4 F4 A4 C5 F5 C5 A4 C5 A4 F4 A4 F4 D4 F4 D4",   # 33
    "C3 B3 G4 B4 D5 F5 D5 B4 D5 B4 G4 B4 D4 F4 E4 D4",   # 34
]

